def cardinal_label(n):
    if not 0 <= n <= 20:
        return np.zeros(6, dtype=int)
    c = np.zeros(6, dtype=int)
    c[int(n >= 3) + int(n >= 7)] = 1
    c[3 + n % 3] = 1
    return c

for knot, coefficients in decoded.items():
    expected = (
        cardinal_label(knot - 1)
        - 2 * cardinal_label(knot)
        + cardinal_label(knot + 1)
    )
