# Count code sums combinatorially, without evaluating any network.
x = sp.Symbol("x")
distribution = sp.Poly(sum((1 + x + x**2)**length
                           for length in range(1, 6)), x)
counts = {s: int(distribution.nth(s)) for s in range(11)}
assert sum(counts.values()) == 363

def fraction(predicate):
    return sum(count for s, count in counts.items() if predicate(s)) / 363

